package dev.danielc.fujiapp;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import org.json.JSONObject;
import android.net.Uri;
import java.util.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class FrameDraftsTest {
 @Test public void restartRestoresIndependentParametersAndCollageOrder()throws Exception{FrameDrafts drafts=new FrameDrafts(RuntimeEnvironment.getApplication());PhotoFrame.Options o=new PhotoFrame.Options();o.style=55;o.paper=4;o.title="Trip";o.filmNote="My film";o.author="A";o.spacing=12;o.parameters=false;o.sidebarRight=true;o.blur=7;o.shadow=30;o.corners=32;JSONObject a=FrameDrafts.snapshot("first","content://image/1","a.jpg",o,Arrays.asList(Uri.parse("content://image/3"),Uri.parse("content://image/2")),2);drafts.save(a);o.title="Second";drafts.save(FrameDrafts.snapshot("second","content://image/4","b.jpg",o,Collections.emptyList(),0));List<JSONObject> loaded=new FrameDrafts(RuntimeEnvironment.getApplication()).list();assertEquals(2,loaded.size());JSONObject restored=loaded.stream().filter(r->r.optString("id").equals("first")).findFirst().get();PhotoFrame.Options actual=new PhotoFrame.Options();FrameDrafts.restore(restored,actual);assertEquals("Trip",actual.title);assertEquals("My film",actual.filmNote);assertEquals(55,actual.style);assertEquals(4,actual.paper);assertEquals(12,actual.spacing);assertFalse(actual.parameters);assertTrue(actual.sidebarRight);assertEquals(7,actual.blur);assertEquals(30,actual.shadow);assertEquals(32,actual.corners);assertEquals("content://image/3",restored.getJSONArray("extras").getString(0));assertEquals(2,restored.getInt("quality"));}
 @Test public void updatingOneDraftAndDeletingItDoesNotTouchSourceOrOthers()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();java.io.File photo=new java.io.File(c.getFilesDir(),"original.jpg");try(java.io.FileOutputStream out=new java.io.FileOutputStream(photo)){out.write(123);}FrameDrafts drafts=new FrameDrafts(c);PhotoFrame.Options o=new PhotoFrame.Options();drafts.save(FrameDrafts.snapshot("one",Uri.fromFile(photo).toString(),"original.jpg",o,Collections.emptyList(),1));o.title="updated";drafts.save(FrameDrafts.snapshot("one",Uri.fromFile(photo).toString(),"original.jpg",o,Collections.emptyList(),1));assertEquals(1,drafts.list().size());assertEquals("updated",drafts.list().get(0).optString("title"));drafts.delete("one");assertTrue(photo.isFile());assertTrue(drafts.list().isEmpty());}
 @Test public void restoreBoundsUnknownIdsAndRejectsPathTraversal()throws Exception{PhotoFrame.Options o=new PhotoFrame.Options();JSONObject r=new JSONObject().put("style",900).put("spacing",-50).put("paper",99);FrameDrafts.restore(r,o);assertEquals(PhotoFrame.NAMES.length-1,o.style);assertEquals(3,o.spacing);assertEquals(4,o.paper);try{new FrameDrafts(RuntimeEnvironment.getApplication()).delete("../original");fail();}catch(IllegalArgumentException expected){}}
 @Test public void interruptedAtomicWriteRecoversBackupEvenWithoutBaseFile()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();FrameDrafts drafts=new FrameDrafts(c);drafts.save(FrameDrafts.snapshot("recovery","content://image/1","original",new PhotoFrame.Options(),Collections.emptyList(),1));java.io.File original=new java.io.File(c.getFilesDir(),"frame-drafts/recovery.json"),backup=new java.io.File(c.getFilesDir(),"frame-drafts/recovery.json.bak");assertTrue(original.renameTo(backup));assertEquals(1,drafts.list().size());assertEquals("recovery",drafts.list().get(0).optString("id"));}
}
